import 'dart:io';

import 'package:path/path.dart' as p;

import '../../common/pubspec_lock.dart';
import '../../init/targets.dart';
import '../config.dart';
import '../context.dart';
import '../rule.dart';

/// R8：生成物（toolkit / AGENTS 片段）由旧版 w_tools_cli 生成。
///
/// 生成物头部带 `generated by w_tools_cli x.y.z`；与 pubspec.lock 里的实际版本
/// 不一致时提示重新运行 init。
class R8GeneratedStale {
  static const id = 'R8';
  static const title = '生成物版本';

  static final _version = RegExp(r'generated by w_tools_cli ([0-9]+\.[0-9]+\.[0-9]+)');

  static DoctorRuleResult check(ProjectContext ctx, DoctorConfig config) {
    final installed = readLockedVersions(ctx.root)['w_tools_cli'];
    if (installed == null) {
      return const DoctorRuleResult(
        ruleId: id,
        title: title,
        status: DoctorRuleStatus.skipped,
        skipReason: 'pubspec.lock 里没有 w_tools_cli（未作为 dev_dependency 安装）',
      );
    }

    final files = <String>{
      config.toolkitEntry,
      ...targetFiles.values,
    }.toList();
    final issues = <DoctorIssue>[];
    var checked = 0;

    for (final rel in files) {
      final file = File(p.join(ctx.root.path, rel));
      if (!file.existsSync()) continue;
      final content = file.readAsStringSync();
      // 用户自己写的 CLAUDE.md / copilot 文件不应该被当成生成物
      if (rel != config.toolkitEntry && !content.contains('<!-- w_tools:begin -->')) {
        continue;
      }
      checked++;
      final match = _version.firstMatch(content);
      if (match == null) {
        issues.add(
          DoctorIssue(
            rule: id,
            level: DoctorLevel.warn,
            file: rel,
            message: '生成物缺少 w_tools_cli 版本标记',
            hint: '运行 dart run w_tools_cli:init --force 重新生成',
            fix: DoctorFix.run('dart run w_tools_cli:init --force'),
          ),
        );
        continue;
      }
      final generatedBy = match.group(1)!;
      if (generatedBy != installed) {
        issues.add(
          DoctorIssue(
            rule: id,
            level: DoctorLevel.warn,
            file: rel,
            message: '由 w_tools_cli $generatedBy 生成，当前安装的是 $installed',
            hint: '运行 dart run w_tools_cli:init --force 刷新生成物（先看 --check-drift 的差异）',
            fix: DoctorFix.run('dart run w_tools_cli:init --force'),
          ),
        );
      }
    }

    if (checked == 0) {
      return const DoctorRuleResult(
        ruleId: id,
        title: title,
        status: DoctorRuleStatus.skipped,
        skipReason: '没有可检查的生成物',
      );
    }

    return DoctorRuleResult(
      ruleId: id,
      title: title,
      status: issues.isEmpty ? DoctorRuleStatus.pass : DoctorRuleStatus.fail,
      issues: issues,
    );
  }
}
